head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.v_SaveKind = ""; // 신규/수정 구분
scwin.vBzProcsNo = ""; // 업무처리번호
scwin.vIsurCd = ""; // 발행기관
scwin.vIsurCd = ""; // 종목코드
scwin.vAcptNo = ""; // 접수번호
scwin.vNapplShrs = 0;
scwin.v_UpdParam = new Array(); // Parent에서 넘어온 데이터들

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // Form onload event
        $c.libRoundPanel.PanelToGroupBox(panel_Item);
        let parentWin = $c.frame.path("../");

        // Transaction 구분: 신규(N), 수정(U)
        scwin.v_SaveKind = parentWin.vQtyApplKind;
        scwin.v_UpdParam = parentWin.v_UpdQtyApplParam;
        scwin.vAcptNo = parentWin.clickAcptNo;
        if (scwin.v_SaveKind === "N") {
            //

        } else if (scwin.v_SaveKind === "U") {
            btn_QtyIsuSave.setBackgroundImage("../img/btn_save_d.gif");
            btn_QtyIsuSave.setDisabled(true);
        }

        // 데이터 조회
        await scwin.selectApplInit();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08022.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_QtyIsuClose_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_QtyIsuClose_onclick = async function() {
    try {
        // 닫기(수량변경)
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08022.btn_QtyIsuClose_onclick" });
    }
};

/**
 * @method
 * @name dts_Itm_IsurDtl_OnLoadError
 * @description dts_Itm_IsurDtl 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Itm_IsurDtl_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Isu);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08022.dts_Itm_IsurDtl_OnLoadError" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        $c.lce.fn_alertMsg('S');
        scwin.parentRefresh();
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08022.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        $c.lce.fn_alertMsg('F');
        await $c.win.alert(trs_Save);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08022.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name img_LIST_DD_onclick
 * @description img_LIST_DD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_LIST_DD_onclick = function() {
    try {
        // 수량변경 > 신청 내역 > 중도상환일 달력 클릭
        popUpCalendar2(edt_HALFWY_REDMPT_DD);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF08022.img_LIST_DD_onclick" });
    }
};

/**
 * @method
 * @name img_BENFCERT_ESTBREPUR_DD_onclick
 * @description img_BENFCERT_ESTBREPUR_DD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_BENFCERT_ESTBREPUR_DD_onclick = function() {
    try {
        // 수량변경 > 신청 내역 > 변경상장일 달력 클릭
        popUpCalendar2(edt_CHG_LIST_DD);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF08022.img_BENFCERT_ESTBREPUR_DD_onclick" });
    }
};

/**
 * @method
 * @name btn_QtyIsuSave_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_QtyIsuSave_onclick = async function() {
    try {
        // 수량변경 > 신청 내역 > 저장버튼 클릭
        await scwin.saveQtyApplInsert();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08022.btn_QtyIsuSave_onclick" });
    }
};

/**
 * @method
 * @name txb_INCDEC_APPL_LIST_SHRS_onkeyup
 * @description txb_INCDEC_APPL_LIST_SHRS 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_INCDEC_APPL_LIST_SHRS_onkeyup = function() {
    try {
        // 수량변경 > 신청 내역 > 세부 > 증감증권수 onkeyup
        if ($c.ut.trim(txb_INCDEC_APPL_LIST_SHRS.getValue()) === "-0") {
            txb_INCDEC_APPL_LIST_SHRS.setValue("0");
        }
        let rsltCalc = 0;
        if ($c.ut.trim(txb_INCDEC_APPL_LIST_SHRS.getValue()) === "" || $c.ut.trim(txb_INCDEC_APPL_LIST_SHRS.getValue()) === "-") {
            rsltCalc = parseInt(txb_CHG_PRE_LIST_SHRS.getValue()) + parseInt(txb_NAPPL_SHRS.getValue());
        } else {
            rsltCalc = parseInt(txb_CHG_PRE_LIST_SHRS.getValue()) + parseInt(txb_INCDEC_APPL_LIST_SHRS.getValue()) + parseInt(txb_NAPPL_SHRS.getValue());
        }
        txb_CHG_AF_LIST_SHRS.setValue(rsltCalc);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF08022.txb_INCDEC_APPL_LIST_SHRS_onkeyup" });
    }
};

/**
 * @method
 * @name txb_LP_HD_QTY_onkeyup
 * @description txb_LP_HD_QTY 키 입력 이벤트
 * @param {*} keycode keycode
 * @param {*} skeycode skeycode
 * @returns {void}
 * @hidden N
 */
scwin.txb_LP_HD_QTY_onkeyup = function(keycode, skeycode) {
    try {
        // 수량변경 > 신청 내역 > 세부 > LP보유수량 onkeyup
        if ($c.ut.trim(txb_LP_HD_QTY.getValue()) === "-0") {
            txb_LP_HD_QTY.setValue("0");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF08022.txb_LP_HD_QTY_onkeyup" });
    }
};

/**
 * @method
 * @name txb_NAPPL_SHRS_onkeyup
 * @description txb_NAPPL_SHRS 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_NAPPL_SHRS_onkeyup = function() {
    try {
        // 수량변경 > 신청 내역  > 세부 > 미반영증권수 onkeyup
        if ($c.ut.trim(txb_NAPPL_SHRS.getValue()) === "-0") {
            txb_NAPPL_SHRS.setValue("0");
        }
        let rsltCalc = 0;
        if ($c.ut.trim(txb_NAPPL_SHRS.getValue()) === "" || $c.ut.trim(txb_NAPPL_SHRS.getValue()) === "-") {
            rsltCalc = parseInt(txb_CHG_PRE_LIST_SHRS.getValue()) + parseInt(txb_NAPPL_SHRS.getValue());
        } else {
            rsltCalc = parseInt(txb_CHG_PRE_LIST_SHRS.getValue()) + parseInt(txb_INCDEC_APPL_LIST_SHRS.getValue()) + parseInt(txb_NAPPL_SHRS.getValue());
        }
        txb_CHG_AF_LIST_SHRS.setValue(rsltCalc);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF08022.txb_NAPPL_SHRS_onkeyup" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name saveQtyApplInsert
 * @description 수량변경 > 신청 내역 > 저장(신규)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.saveQtyApplInsert = async function() {
    if ($c.en.fn_CheckForm(scwin.v_SaveKind) === false) return;
    const TR_JOB = 'I';

    // Transaction 처리전 안내문구
    if ($c.ut.trim(txb_INCDEC_APPL_LIST_SHRS.getValue()) === "") {
        txb_INCDEC_APPL_LIST_SHRS.setValue("0");
    }
    if (parseInt(txb_INCDEC_APPL_LIST_SHRS.getValue()) > 0) {
        LastJob = '저장'; // list_common_etn.js에 있는 상장메세지처리관련
        // var rstlMsg = confirm("[증감증권수]는 0 이하의 수만 입력가능합니다.\n\n현재 상태로 [저장] 처리하시겠습니까?");
        // if (rstlMsg == false) {
        //    return;
        // }
        await $c.win.alert("[증감증권수]는 0 이하의 수만 입력가능합니다.");
        return;
    } else {
        let isNApplShrs = true;

        // 제출에서 오는 변경후 데이터가 틀릴 수 있으므로, 미반영에 대한 체크를 한 번 더 해줌
        const totShrs = parseInt(txb_CHG_PRE_LIST_SHRS.getValue()) + parseInt(txb_INCDEC_APPL_LIST_SHRS.getValue()) + parseInt(txb_NAPPL_SHRS.getValue());
        if (totShrs !== parseInt(txb_CHG_AF_LIST_SHRS.getValue())) {
            isNApplShrs = confirm("[미반영건수] 가 " + scwin.vNapplShrs + " 건 있습니다.\n[변경후 증권수] 에 반영하고 처리합니다.\n\n[저장] 처리하시겠습니까?");
            if (!isNApplShrs) {
                return;
            } else {
                LastJob = '저장'; // list_common_etn.js에 있는 상장메세지처리관련
                txb_CHG_AF_LIST_SHRS.setValue(parseInt(txb_CHG_PRE_LIST_SHRS.getValue()) + parseInt(txb_INCDEC_APPL_LIST_SHRS.getValue()) + parseInt(txb_NAPPL_SHRS.getValue()));
            }
        } else {
            if (!$c.lce.fn_isProcess(TR_JOB)) {
                return;
            } else {
                txb_CHG_AF_LIST_SHRS.setValue(parseInt(txb_CHG_PRE_LIST_SHRS.getValue()) + parseInt(txb_INCDEC_APPL_LIST_SHRS.getValue()) + parseInt(txb_NAPPL_SHRS.getValue()));
            }
        }
    }
    const vScrenId = "SCREN_ID=" + "ULDSTF08022.xml";
    const vScrenTpId = "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    const vSrvMethod = "&method=insertQtyApplDtl";
    scwin.vBzProcsNo = await $c.stf.getNewBzProcNo(dts_BzProcsNo); // 업무처리번호 새로 지정
    scwin.vIsurCd = scwin.v_UpdParam[1]; // 발행기관코드

    trs_Save.KeyName = "toinb_dataid4";
    // [전환검토] trs_Save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    //     TRS_IDX : TR_JOB_INSERT,
    //     LIST_BZ_TP_CD : LIST_BZ_TP_CD_708,
    //     BZ_PROCS_NO : scwin.vBzProcsNo,
    //     ISUR_CD : scwin.vIsurCd,
    //     LD_MKT_TP_CD : "1",
    //     TRANSTR_EMP_NO : js_emp_no,
    //     ACPT_NO : scwin.vAcptNo
    // };
    const sbmOptions = {
        id : "sbm_trs_Save",
        action : "/etn/EtnChgList.do",
        ref : "dts_Isu",
        target : "trs_Save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name selectApplInit
 * @description 종목코드에 대한 발행회사 조회 / 신규시 초기화됨
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.selectApplInit = async function() {
    // 조회조건
    /*	1. 수량변경 신청내역 조회	*/
    url += "&SCREN_ID=" + "ULDSTF08022.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&ACPT_NO=" + scwin.vAcptNo;
    //    url += "&SRCH_ISU_CD=" + v_UpdParam[0];
    //    url += "&SRCH_COM_CD=" + v_UpdParam[1];

    const sbmOptions = {
        id : "sbm_dts_Isu",
        action : "/etn/EtnChgList.do",
        ref : "",
        target : "dts_Isu=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 제출에서 오는 변경후 데이터가 틀릴 수 있으므로, 미반영에 대한 체크를 한 번 더 해줌
    // txb_CHG_AF_LIST_SHRS.text = parseInt(txb_CHG_PRE_LIST_SHRS.text) + parseInt(txb_INCDEC_APPL_LIST_SHRS.text) + parseInt(txb_NAPPL_SHRS.text);
    // 미반영건수 (저장시 체크하기 위함. 이유는 제출시스템에서 오는 데이터는 미반영건수에 대한 데이터가 아닐 수 있으므로, 그냥 저장할 때 체크해야 함)
    scwin.vNapplShrs = parseInt(txb_NAPPL_SHRS.getValue());
};

///////// 5. 일반/업무 함수 영역 /////////
// 미반영건수

/**
 * @method
 * @name checkForm
 * @description Form Validation Check
 * @param {*} kind kind
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function(kind) {
    const vCurDate = $c.ut.cGetToday("yyyymmdd");
    if (edt_HALFWY_REDMPT_DD.getValue() === "") {
        await $c.win.alert("[중도상환일]을 입력하세요.");
        edt_HALFWY_REDMPT_DD.focus();
        return false;
    } else if (edt_CHG_LIST_DD.getValue() === "") {
        await $c.win.alert("[변경상장일]을 입력하세요.");
        edt_CHG_LIST_DD.focus();
        return false;
    } else if (vCurDate >= edt_CHG_LIST_DD.getValue()) {
        await $c.win.alert("[변경상장일]을 현재일이후로 입력하세요.");
        edt_CHG_LIST_DD.focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name checkNumeric
 * @description 숫자입력체크
 * @returns {void}
 * @hidden N
 */
scwin.checkNumeric = function() {
    let key = window.event ? window.event.keyCode : window.event.which;

    // 방향키 좌우, home, end (35,36,37,39)
    // del, back space (8, 46)
    if ((event.shiftKey === false) && ((key > 47 && key < 58) || (key > 95 && key < 106) ||
            key === 35 || key === 36 || key === 37 || key === 39 ||
            key === 8 || key === 46)) {
        return true;
    } else {
        return false;
    }
};

/**
 * @method
 * @name onlyNumber
 * @description 숫자만 입력 가능
 * @returns {void}
 * @hidden N
 */
scwin.onlyNumber = function() {
    let key = window.event ? window.event.keyCode : window.event.which;
    if ((key < 48) || (key > 57)) {
        window.event.returnValue = false;
    }
};

/**
 * @method
 * @name parentRefresh
 * @description Parent 화면 Refresh()
 * @returns {void}
 * @hidden N
 */
scwin.parentRefresh = function() {
    // Parent 신청내역 화면 Refresh
    let parentWin = $c.frame.path("../");
    parentWin.txb_SearchIsuCd.setValue(txb_ISU_CD.getValue());
    parentWin.txb_SearchIsuNm.setValue(txb_ISU_NM.getValue());
    parentWin.cmb_ISUR_CD.setValue(scwin.vIsurCd);
    parentWin.fn_list_qty_appl(scwin.vIsurCd, txb_ISU_CD.getValue());
    parentWin.fn_list_sync();
};
